#!/usr/bin/env bash
# Experiments L / O / B of docs/followup_experiments_plan.md (pre-registered 2026-10-14).
#   L      label-efficiency curve: E1 vs E8 on 10/25/50% of the Gold training reviews, 5 seeds, two epoch schedules
#   OX OD  overall-rating-only pretraining (one head) on XLM-R (2024 pool) and DeBERTa (2021-24 pool) + E8 x 3 seeds
#   LUKE BERTL XLMRL   E7 (2021-24 pool, 1 epoch) + E8 x 3 seeds on the three encoders A' did not cover
# Runs are skipped if their output exists. Do not edit this file while a queue is running.
#
# Usage:  GPU=0 bash tools/run_followup_experiments.sh L OX OD
#         GPU=1 bash tools/run_followup_experiments.sh LUKE BERTL XLMRL
set -euo pipefail
cd "$(dirname "$0")/.."

GPU="${GPU:-0}"
PY=.venv/bin/python
LOG_DIR=logs/followup
mkdir -p "$LOG_DIR"
export CUDA_VISIBLE_DEVICES="$GPU" TOKENIZERS_PARALLELISM=false
export HF_HOME="$(cd .. && pwd)/hf_cache/home"  # everything else Hugging Face writes (xet download logs, ...)
export HF_HUB_CACHE="$(cd .. && pwd)/hf_cache"  # project-local model cache; never write outside gujincheng/
export HF_DATASETS_CACHE="$(cd .. && pwd)/hf_cache/datasets"  # datasets cache holds licensed text: keep it inside gujincheng/
FT="--loss_type asl --asl_gamma_neg 4.0 --asl_clip 0.05 --no_pos_weight --tune_threshold"
ALL="--train_file data/weak_all/panel_weak_train.jsonl --validation_file data/weak_all/panel_weak_valid.jsonl \
     --stats_file data/weak_all/panel_weak_label_stats_all.json --num_epochs 1 --max_valid_samples 50000"
MAIN_E7=checkpoints/absa_weak_pretrain_v1/encoder  # main-line E7: 2024 pool, 2 epochs, seed 42

ft() {  # name seed extra-args...   one fine-tuning run (E1 without, E8 with --pretrained_encoder)
  local name=$1 seed=$2; shift 2
  if [[ -f "results/${name}_metrics.json" ]]; then echo "[skip] $name"; return 0; fi
  echo "[$(date +%F' '%T)] $name"
  $PY train_absa_baseline.py $FT --seed "$seed" "$@" --output_dir "checkpoints/tmp_$name" \
      --experiment_name "$name" > "$LOG_DIR/$name.log" 2>&1 \
    || { echo "[$(date +%F' '%T)] FAILED $name (see $LOG_DIR/$name.log)"; rm -rf "checkpoints/tmp_${name:?}"; return 0; }
  rm -rf "checkpoints/tmp_${name:?}"
}

e7() {  # name extra-args...   one weak-supervision pretraining run; keeps only the encoder
  local name=$1; shift
  if [[ -f "checkpoints/$name/encoder/model.safetensors" ]]; then echo "[skip] E7 $name"; return 0; fi
  echo "[$(date +%F' '%T)] E7 $name"
  $PY train_panel_weak_pretrain.py --pos_weight_mode sqrt --output_dir "checkpoints/$name" \
      --experiment_name "$name" "$@" > "$LOG_DIR/$name.log" 2>&1 \
    || { echo "[$(date +%F' '%T)] FAILED E7 $name (see $LOG_DIR/$name.log)"; return 1; }
  rm -rf "checkpoints/${name:?}"/checkpoint-*
}

L() {
  local sched f ep s tr
  for s in 45 46; do ft "L_E8_f100_seed$s" "$s" --pretrained_encoder "$MAIN_E7"; done  # completes 5 seeds at 100%
  for sched in a b; do
    for f in 50 25 10; do
      ep=3
      if [[ $sched == b ]]; then case $f in 50) ep=6 ;; 25) ep=12 ;; 10) ep=30 ;; esac; fi
      for s in 42 43 44 45 46; do
        tr="data/ablation/lowres/absa_train_f${f}_s${s}.csv"
        ft "L${sched}_E1_f${f}_seed$s" "$s" --train_file "$tr" --num_train_epochs "$ep"
        ft "L${sched}_E8_f${f}_seed$s" "$s" --train_file "$tr" --num_train_epochs "$ep" --pretrained_encoder "$MAIN_E7"
      done
    done
  done
}

OX() {  # XLM-R, 2024 pool, 2 epochs (the main-line E7 setting) with the overall rating as the only head
  local E7=O_E7_xlmr_overall_2024 s
  e7 "$E7" --heads overall || return 0
  for s in 42 43 44; do ft "O_E8_xlmr_overall_seed$s" "$s" --pretrained_encoder "checkpoints/$E7/encoder"; done
}

OD() {  # DeBERTa, 2021-24 pool, 1 epoch (the E7_deberta_recent2M setting) with the overall rating as the only head
  local E7=O_E7_deberta_overall_recent2M s
  # ku-nlp/deberta-v3-base-japanese (revision 0c320ba8, the one E7_deberta_recent2M used) is only in the shared
  # cache: read it in place, read-only, via its snapshot directory. Nothing is written there.
  local DEBERTA=/home/etl/.cache/huggingface/hub/models--ku-nlp--deberta-v3-base-japanese/snapshots/0c320ba8f63dcbb8adb049a79349437fa5728ac9
  e7 "$E7" $ALL --min_source_year 2021 --model_name "$DEBERTA" --heads overall || return 0
  for s in 42 43 44; do ft "O_E8_deberta_overall_seed$s" "$s" --pretrained_encoder "checkpoints/$E7/encoder"; done
}

backbone() {  # tag model   same arguments as A' (Aprime_E7_modernbert310m_recent2M), only the model changes
  local tag=$1 model=$2 E7="B_E7_${1}_recent2M" s
  if [[ ! -f "checkpoints/$E7/encoder/model.safetensors" && ! -f "$LOG_DIR/SMOKE_$tag.ok" ]]; then
    echo "[$(date +%F' '%T)] smoke test $tag"
    $PY train_panel_weak_pretrain.py $ALL --min_source_year 2021 --pos_weight_mode sqrt --model_name "$model" --smoke \
        --experiment_name "SMOKE_$tag" --results_dir "$LOG_DIR/smoke" > "$LOG_DIR/SMOKE_$tag.log" 2>&1 \
      || { echo "[$(date +%F' '%T)] FAILED smoke test $tag (see $LOG_DIR/SMOKE_$tag.log)"; return 0; }
    rm -rf checkpoints/smoke_e7
    touch "$LOG_DIR/SMOKE_$tag.ok"
  fi
  e7 "$E7" $ALL --min_source_year 2021 --model_name "$model" || return 0
  for s in 42 43 44; do ft "B_E8_${tag}_seed$s" "$s" --pretrained_encoder "checkpoints/$E7/encoder"; done
}
LUKE()  { backbone luke_ja studio-ousia/luke-japanese-base-lite; }
BERTL() { backbone bert_large_ja tohoku-nlp/bert-large-japanese-v2; }
XLMRL() { backbone xlmr_large xlm-roberta-large; }

for step in "$@"; do
  case "$step" in
    L|OX|OD|LUKE|BERTL|XLMRL) echo "[$(date +%F' '%T)] === $step ==="; "$step" ;;
    *) echo "unknown step: $step"; exit 2 ;;
  esac
done
echo "[$(date +%F' '%T)] follow-up queue done: $*"
